WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM payments), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT method, AVG(burst_id) FILTER (WHERE method = 'paypal') AS paypal_avg_burst_id, APPROX_PERCENTILE(is_new_session, 0.9) AS is_new_session_p90, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) AS burst_id_per_success FROM islands GROUP BY method
